head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


/**=============================================================
* 시장조성자 관련 공통 스크립트 
* fn_get_marketMaker	기준일자의 시장조성자 목록 조회 
* fn_get_AgBzDd			작업일자의 전일자 영업일 조회 
* fn_get_ClsLpSndLog	작업일자의 마감정보 조회
*=============================================================/


/**
  * 기준일자의 시장조성자 가져오기 
 * @param dtsObj
 * @param vBasDd	기준일자 
 * @param vSpotIsuTrdMktTpCd	현물종목거래시장구분코드 
  */
/**
 * @method
 * @name fn_get_marketMaker
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} vBasDd desc
 * @param {string} vSpotIsuTrdMktTpCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_get_marketMaker = function(dtsObj, vBasDd, vSpotIsuTrdMktTpCd) {
    var url = "/MarketMakerLPHdQtyAdm.do?SCREN_ID=" + vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=marketmakerNameList";
    url += "&inputMessageId=MARKETMAKERNAMELIST_INOUT&outputMessageId=MARKETMAKERNAMELIST_INOUT";
    url += "&BAS_DD=" + vBasDd;
    url += "&SPOT_ISU_TRD_MKT_TP_CD=" + vSpotIsuTrdMktTpCd;
    dtsObj.DataID = encodeURI(url);
    dtsObj.Reset();
    dtsObj.InsertRow(1);
    dtsObj.setCellData(1, "MKTPARTC_NM", "전체");
};




/**
 * 작업일자의 전일자 영업일 가져오기 
 * @param dtsObj
 * @param vTaskDd	작업일자 
 */
/**
 * @method
 * @name fn_get_AgBzDd
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} vTaskDd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_get_AgBzDd = function(dtsObj, vTaskDd) {
    var url = "/MarketMakerLPHdQtyAdm.do?SCREN_ID=" + vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=dd1AgBzDdList";
    url += "&inputMessageId=DD1AGBZDDLIST_INOUT&outputMessageId=DD1AGBZDDLIST_INOUT";
    url += "&DATE=" + vTaskDd;
    dtsObj.DataID = encodeURI(url);
    dtsObj.Reset();
};






/**
 * 작업일자의 마감정보 
 * @param dtsObj
 * @param vTaskDd	작업일자 
 */
/**
 * @method
 * @name fn_get_ClsLpSndLog
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} vTaskDd desc
 * @param {string} vTrdMkt desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_get_ClsLpSndLog = function(dtsObj, vTaskDd, vTrdMkt) {
    var url = "/MarketMakerLPHdQtyAdm.do?SCREN_ID=" + vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=selectClsLpSndLog";
    url += "&inputMessageId=MMLPSNDLOG_INOUT&outputMessageId=MMLPSNDLOG_INOUT";
    url += "&TASK_DD=" + vTaskDd;
    url += "&SPOT_ISU_TRD_MKT_TP_CD=" + vTrdMkt;
    dtsObj.DataID = encodeURI(url);
    dtsObj.Reset();
};
